"""Quote-led catalogue, rental packages and explicit service scopes. Paired EN/FR copy."""

def c(en,fr): return esc(copy(en,fr))
def qlink(label,need,topic='',package=''):
 params={'need':need}
 if topic:params['topic']=topic
 if package:params['package']=package
 return link('/quote/?'+esc(urlencode(params)),label,'button navy')
def quick_links(items):
 return '<nav class="offering-jumps wrap" aria-label="'+c('Explore this page','Explorer cette page')+'">'+''.join(link(url,label) for url,label in items)+'</nav>'
def symbol(kind):
 shapes={
 'flags':'<path d="M56 128V30m0 5c26-15 39 15 68 0v48c-29 15-42-15-68 0"/>',
 'poles':'<path d="M65 132V25m0 7h52l-10 19 10 19H65m-17 62h34m-28-12h22"/>',
 'parts':'<path d="M58 49a17 17 0 0 1 34 0v28a17 17 0 0 1-34 0V49Zm21 28a17 17 0 0 1 34 0v28a17 17 0 0 1-34 0V77Z"/>',
 'complete':'<path d="M65 120V28m0 8h52l-10 18 10 18H65m-12 48h24l9 12H44l9-12Z"/>',
 'logistics':'<path d="M33 107V52h65v55H33Zm65-39h20l16 21v18H98M49 52V24m0 6h35v17H49"/><circle cx="55" cy="114" r="10"/><circle cx="116" cy="114" r="10"/>'}
 return '<svg class="offering-symbol" viewBox="0 0 170 160" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+shapes[kind]+'</svg>'

# Catalogue entries are configurable product families, never invented stock items or SKUs.
catalogue=[]
for family,records,base,need in [('flags',FLAGS,'flags','Buy Flags'),('poles',POLES,'flagpoles','Buy Flagpole'),('parts',PARTS,'accessories','Other')]:
 for record in records:
  slug,title,_,description=record[:4]
  catalogue.append({'id':family+'-'+slug,'category':family,'title':title,'description':description,'url':f'/{base}/{slug}/','need':'Custom Flags' if family=='flags' and slug in ('custom','corporate') else need})
(ROOT/'catalog.json').write_text(json.dumps({'currency':'CAD','mode':'quote','recordType':'product-family','categories':['flags','poles','parts'],'products':catalogue,'commerceEnabled':False},ensure_ascii=False,indent=2)+'\n')
labels={'flags':copy('Flags','Drapeaux'),'poles':copy('Flagpoles','Mâts'),'parts':copy('Parts & accessories','Pièces et accessoires')}
catalog_title=copy('Product catalogue','Catalogue de produits')
catalog_desc=copy('Browse flags, flagpoles and accessories. Compare product families and request pricing for your quantity, dimensions and location.','Parcourez les drapeaux, mâts et accessoires. Comparez les familles de produits et demandez un prix selon les quantités, dimensions et destination.')
body='<header class="guide-hero wrap"><p class="eyebrow">'+c('FIND YOUR DISPLAY','TROUVEZ VOTRE INSTALLATION')+'</p><h1>'+esc(catalog_title)+'</h1><p class="lead">'+esc(catalog_desc)+'</p></header>'
body+='<section class="wrap catalogue-section"><div class="catalogue-toolbar" hidden><label for="catalogue-search">'+c('Search the catalogue','Rechercher dans le catalogue')+'</label><input id="catalogue-search" type="search" placeholder="'+c('Try Canadian flags, portable poles or clips','Essayez drapeaux canadiens, mâts portatifs ou attaches')+'" maxlength="160" aria-controls="catalogue-grid"><div class="search-filters" role="group" aria-label="'+c('Product categories','Catégories de produits')+'">'
for family,label in [('',copy('All products','Tous les produits'))]+list(labels.items()):
 body+='<button type="button" data-catalogue-filter="'+family+'" aria-pressed="'+('true' if not family else 'false')+'">'+esc(label)+'</button>'
body+='</div><p id="catalogue-status" role="status" aria-live="polite"></p></div><p class="catalogue-note">'+c('Choose a product family to see what to specify. Sizes, materials, compatibility, availability and pricing are confirmed in your quote.','Choisissez une famille de produits pour connaître les détails à préciser. Formats, matières, compatibilité, disponibilité et prix sont confirmés dans la soumission.')+'</p><div id="catalogue-grid" class="catalogue-grid">'
for item in catalogue:
 body+='<article class="catalogue-card" data-category="'+item['category']+'">'+symbol(item['category'])+'<div><p class="eyebrow">'+esc(labels[item['category']])+'</p><h2>'+link(item['url'],esc(item['title']))+'</h2><p>'+esc(item['description'])+'</p><div class="catalogue-actions">'+link(item['url'],c('VIEW OPTIONS','VOIR LES OPTIONS'),'text-link')+qlink(c('GET PRICING','OBTENIR UN PRIX'),item['need'],item['title'])+'</div></div></article>'
body+='</div><div id="catalogue-empty" class="empty-state" hidden><h2>'+c('No matching products','Aucun produit correspondant')+'</h2><p>'+c('Try another term or reset the filters. We can also help identify a product from your photos or description.','Essayez un autre terme ou réinitialisez les filtres. Nous pouvons aussi vous aider à identifier un produit à partir de photos ou d’une description.')+'</p><button type="button" id="catalogue-reset" class="button navy">'+c('RESET FILTERS','RÉINITIALISER LES FILTRES')+'</button></div></section><script defer src="/assets/catalogue.js"></script>'
body+='<section class="content-band"><div class="wrap two-column"><div><h2>'+c('Buying, renting or replacing?','Acheter, louer ou remplacer?')+'</h2><p>'+c('Use the catalogue for product enquiries. For a temporary event or an existing display that needs attention, start with the matching service.','Utilisez le catalogue pour vos demandes de produits. Pour un événement temporaire ou une installation à entretenir, choisissez le service correspondant.')+'</p></div><div class="offering-links">'+link('/flag-rentals/',c('Compare rental packages','Comparer les formules de location'))+link('/services/',c('Find an installation or service','Trouver un service ou une installation'))+link('/resources/choosing-a-flag/',c('Read the flag buying guide','Lire le guide d’achat de drapeaux'))+'</div></div></section>'
add('/catalogue/',catalog_title,catalog_desc,body,'CollectionPage')
# Make the catalogue discoverable from existing entry points and product details.
for path in ['/flags/','/flagpoles/','/accessories/']:
 p=PAGES[path]
 callout='<div class="wrap catalogue-callout"><span>'+c('Compare the range in one place.','Comparez la gamme au même endroit.')+'</span>'+link('/catalogue/',c('BROWSE PRODUCT CATALOGUE','PARCOURIR LE CATALOGUE'),'text-link')+'</div>'
 p['body']=p['body'].replace('</section>','</section>'+callout,1)
for item in catalogue:
 p=PAGES[item['url']]
 p['body']=p['body'].replace('</section>','</section>'+quick_links([('/catalogue/',c('All products','Tous les produits')),('/resources/choosing-a-flagpole/' if item['category']!='flags' else '/resources/choosing-a-flag/',c('Help me choose','Aidez-moi à choisir'))]),1)
PAGES['/']['body']=PAGES['/']['body'].replace('<a class="button outline light" href="/flags/">EXPLORE FLAGS</a>','<a class="button outline light" href="/catalogue/">'+c('BROWSE PRODUCTS','PARCOURIR LES PRODUITS')+'</a>')

packages=[
 ('flag-only',('Flag only','Drapeau seul'),'Flag Rental','flags',('For a venue with compatible poles or stands.','Pour un lieu disposant de mâts ou supports compatibles.'),[('Rental flags in the agreed designs and quantities','Drapeaux loués selon les dessins et quantités convenus'),('Size and attachment compatibility reviewed','Format et compatibilité des fixations à vérifier')],('Your existing poles and bases stay in use. Send photos and dimensions so we can check the fit.','Vous utilisez vos mâts et bases existants. Joignez des photos et dimensions pour vérifier la compatibilité.')),
 ('display-system',('Flag, pole & base','Drapeau, mât et base'),'Flagpole Rental','complete',('For a complete temporary display.','Pour une installation temporaire complète.'),[('Rental flags, compatible poles and bases','Drapeaux, mâts et bases compatibles en location'),('Display configuration matched to the venue','Configuration adaptée au lieu')],('Tell us about the surface, ceiling clearance and indoor or outdoor use. Transport and setup are agreed separately.','Précisez le sol, la hauteur libre et l’usage intérieur ou extérieur. Transport et montage sont convenus séparément.')),
 ('event-service',('Full-service event package','Formule événement avec services'),'Flag Rental','logistics',('For a display with coordinated event logistics.','Pour une installation avec logistique événementielle coordonnée.'),[('Flags, poles and bases in the agreed display plan','Drapeaux, mâts et bases du plan convenu'),('Delivery, setup, takedown and collection requested together','Livraison, montage, démontage et ramassage demandés ensemble')],('Share both access windows and the venue contact.','Précisez les deux plages d’accès et le contact sur place.'))]
rental_title=copy('Flag & flagpole rentals','Location de drapeaux et de mâts')
rental_intro=copy('Rent a flag, a complete display or an event package with delivery and setup. Compare the options, then share your dates, venue and quantities.','Louez un drapeau, une installation complète ou une formule avec livraison et montage. Comparez les options, puis indiquez dates, lieu et quantités.')
body=hero(copy('HERE FOR THE OCCASION','POUR VOTRE OCCASION'),rental_title,rental_intro,'event')
body=body.replace('href="/quote/"','href="#rental-packages"',1).replace('GET A QUOTE',copy('COMPARE PACKAGES','COMPARER LES FORMULES'),1)
body+=quick_links([('#rental-packages',c('Rental packages','Formules de location')),('#rental-planning',c('Dates & logistics','Dates et logistique')),('#rental-questions',c('Rental questions','Questions de location'))])
body+='<section id="rental-packages" class="wrap section offering-section">'+section_head(copy('THREE WAYS TO RENT','TROIS FORMULES DE LOCATION'),copy('Choose the help you need.','Choisissez l’aide nécessaire.'),copy('Package pricing is by quote. Your confirmed proposal lists the exact equipment, services and rental period.','Les prix sont établis par soumission. La proposition confirmée précise le matériel, les services et la période de location.'))+'<div class="package-grid">'
for index,(identifier,title,need,icon,intro,includes,note) in enumerate(packages):
 name=copy(*title)
 body+='<article class="package-card">'+symbol(icon)+'<p class="eyebrow">0'+str(index+1)+'</p><h3>'+esc(name)+'</h3>'+para(*intro)+'<h4>'+c('Scope to request','Portée à demander')+'</h4>'+checklist(includes)+'<p class="package-note">'+c(*note)+'</p>'+qlink(c('REQUEST THIS PACKAGE','DEMANDER CETTE FORMULE'),need,name,identifier)+'</article>'
body+='</div></section>'
body+='<section id="rental-planning" class="content-band offering-section"><div class="wrap two-column"><div><p class="eyebrow">'+c('PLAN THE WHOLE RENTAL','PLANIFIEZ TOUTE LA LOCATION')+'</p><h2>'+c('From setup day to collection.','Du montage au ramassage.')+'</h2><p>'+c('Include the days you need the equipment for setup, rehearsals and takedown. Your event dates alone may not cover the full rental period.','Incluez les jours nécessaires au montage, aux répétitions et au démontage. Les dates de l’événement peuvent ne pas couvrir toute la location.')+'</p>'+link('/resources/rental-planning/',c('READ THE RENTAL PLANNING GUIDE','LIRE LE GUIDE DE LOCATION'),'text-link')+'</div><div>'+checklist([('Flag designs, quantities and display positions.','Dessins, quantités et emplacements des drapeaux.'),('Venue address, indoor or outdoor setting and surface.','Adresse, usage intérieur ou extérieur et type de sol.'),('Equipment start and collection dates; venue access times.','Dates de début et de ramassage; heures d’accès.'),('Delivery, setup, takedown and collection services you want quoted.','Services de livraison, montage, démontage et ramassage à chiffrer.')])+'</div></div></section>'
body+='<section class="wrap section">'+section_head(copy('YOUR EVENT','VOTRE ÉVÉNEMENT'),copy('Plan around the occasion.','Planifiez selon l’occasion.'))+cards([(t,'/flag-rentals/'+s+'/',d) for s,t,d,p in RENTALS])+'</section>'
answers=[
 (('What does a rental package include?','Que comprend une formule de location?'),('Flag-only requests use your compatible display hardware. A display-system request adds poles and bases. The event package also requests delivery, setup, takedown and collection. Exact inclusions are confirmed in the quote.','La formule drapeau seul utilise votre matériel compatible. La formule complète ajoute mâts et bases. La formule événement inclut une demande de livraison, montage, démontage et ramassage. Les inclusions exactes sont confirmées dans la soumission.')),
 (('How are rental prices calculated?','Comment les prix de location sont-ils calculés?'),('Pricing depends on the flag designs and quantities, equipment, full rental period, venue location and requested services. Share those details for a quote that separates equipment from logistics.','Le prix dépend des dessins et quantités, du matériel, de la durée totale, du lieu et des services demandés. Ces détails permettent de distinguer le matériel de la logistique dans la soumission.')),
 (('Can I use rental displays outdoors?','Puis-je utiliser les installations louées à l’extérieur?'),('Outdoor suitability depends on the selected flag, pole, base, surface and exposure. Describe the venue and placement before choosing equipment; an indoor base is not automatically suitable outside.','L’aptitude à l’extérieur dépend du drapeau, du mât, de la base, du sol et de l’exposition. Décrivez le lieu avant de choisir le matériel; une base intérieure ne convient pas automatiquement à l’extérieur.')),
 (('What should I confirm before booking?','Que faut-il confirmer avant de réserver?'),('Confirm availability, the full rental period, included equipment and services, access windows, transport charges and any deposit, damage, change or cancellation terms. A quote request does not reserve equipment.','Confirmez la disponibilité, la durée, le matériel et les services inclus, les plages d’accès, les frais de transport et les conditions de dépôt, dommage, modification ou annulation. Une demande de soumission ne réserve pas le matériel.'))]
body+='<div id="rental-questions" class="offering-section">'+faq([(copy(*q),copy(*a)) for q,a in answers])+'</div>'
add('/flag-rentals/',rental_title,copy('Compare flag-only, flag with pole and base, and full-service event rental packages. Request equipment and logistics for your venue and dates.','Comparez les locations de drapeaux seuls, de drapeaux avec mâts et bases, et les formules événement avec services. Demandez matériel et logistique pour vos dates et votre lieu.'),body)
for s,*_ in RENTALS:
 p=PAGES['/flag-rentals/'+s+'/']
 p['body']=p['body'].replace('</section>','</section>'+quick_links([('/flag-rentals/#rental-packages',c('Compare rental packages','Comparer les formules de location')),('/resources/rental-planning/',c('Plan dates & logistics','Planifier les dates et la logistique'))]),1)

# Literal service headings and matching request types preserve existing route authority.
service_routes=['/flagpole-installation/','/flag-service/','/commercial-accounts/','/services/specialist/']+['/'+s+'/' for s,*_ in SERVICES]+['/services/'+r[0]+'/' for r in MICROS]+['/flagpole-installation/'+s+'/' for s,*_ in INSTALL]
for route in service_routes:
 p=PAGES[route]
 p['body']=re.sub(r'<h1>.*?</h1>','<h1>'+esc(p['title'])+'</h1>',p['body'],count=1)
 # The legacy generic service CTA incorrectly chose Repair on every service page.
 p['body']=p['body'].replace('href="/quote/?need=Flagpole%20Repair">BOOK SERVICE',f'href="{esc(quote_context(route))}">'+copy('REQUEST THIS SERVICE','DEMANDER CE SERVICE'))
 if route.startswith('/flagpole-installation/'):
  scope=copy('Your quote separates the pole and hardware, site preparation, foundation or fixing work, access equipment, delivery and installation. Any approvals, specialist input or removal work are agreed for the site.','La soumission distingue le mât et la quincaillerie, la préparation, les fondations ou fixations, l’accès, la livraison et l’installation. Autorisations, expertise et retrait sont convenus selon le site.')
 elif route in ('/flag-service/','/commercial-accounts/','/flagpole-maintenance/'):
  scope=copy('Agree the locations, visit frequency, flag supply, replacement work and checks to be performed. Access arrangements, reporting and any separately quoted repairs are identified before the program starts.','Convenez des lieux, de la fréquence, des drapeaux à fournir, des remplacements et vérifications. Accès, rapports et réparations chiffrées séparément sont précisés avant le début du programme.')
 else:
  scope=copy('The proposal identifies the task, replacement products or parts, access equipment, site arrangements and timing.','La proposition précise les travaux, produits ou pièces de remplacement, équipements d’accès, modalités sur place et calendrier.')
 block='<section class="wrap service-scope"><div><p class="eyebrow">'+c('A CLEAR SCOPE','UNE PORTÉE CLAIRE')+'</p><h2>'+c('What your service quote covers','Ce que précise votre soumission')+'</h2><p>'+esc(scope)+'</p></div><div><h3>'+c('Start with these details','Commencez par ces détails')+'</h3>'+checklist([('City or site address and preferred dates.','Ville ou adresse du site et dates souhaitées.'),('Number of poles, approximate height and what needs doing.','Nombre de mâts, hauteur approximative et travaux nécessaires.'),('Ground-level photos and any existing product records.','Photos prises au sol et documents des produits existants.')])+link(esc(quote_context(route)),c('REQUEST THIS SERVICE','DEMANDER CE SERVICE'),'button navy')+'</div></section>'
 p['body']=p['body'].replace('</section>','</section>'+block,1)

service_title=copy('Flagpole installation, repair & service','Installation, réparation et entretien de mâts')
service_intro=copy('Install a new flagpole, fix an existing display, replace a flag or plan regular care. Choose the work you need to see the scope and prepare your request.','Installez un mât, réparez une installation, remplacez un drapeau ou planifiez l’entretien. Choisissez les travaux pour connaître la portée et préparer votre demande.')
body=hero(copy('SERVICES FOR YOUR DISPLAY','SERVICES POUR VOTRE INSTALLATION'),service_title,service_intro,'hardware')
body+='<section class="wrap section">'+section_head(copy('START WITH THE JOB','COMMENCEZ PAR LES TRAVAUX'),copy('What needs doing?','Quels travaux faut-il prévoir?'))+cards([
 (copy('Install a flagpole','Installer un mât'),'/flagpole-installation/',copy('New, replacement and multiple-pole installations, with site preparation and access considered.','Installations neuves, de remplacement ou de plusieurs mâts, avec préparation et accès adaptés.')),
 (copy('Repair a flagpole','Réparer un mât'),'/flagpole-repair/',copy('Ropes, operating problems and damaged hardware. Start with the symptom and pole details.','Cordages, problèmes de manœuvre et quincaillerie endommagée. Décrivez le problème et le mât.')),
 (copy('Replace a flag','Remplacer un drapeau'),'/flag-replacement/',copy('Match the flag design, size and attachment to the existing display.','Adaptez le dessin, le format et la fixation à l’installation existante.')),
 (copy('Plan ongoing care','Planifier l’entretien'),'/flag-service/',copy('One-time, seasonal, quarterly or multi-location service with agreed tasks and frequency.','Service ponctuel, saisonnier, trimestriel ou multisite selon les tâches et la fréquence convenues.'))])+'</section>'
body+='<section class="content-band"><div class="wrap">'+section_head(copy('SPECIFIC SERVICES','SERVICES PRÉCIS'),copy('Find the task that fits.','Trouvez le service adapté.'))+cards([(t,'/'+s+'/',d) for s,t,h,d,p,n in SERVICES if s not in ('flagpole-repair','flag-replacement')]+[(r[1],'/services/'+r[0]+'/',r[3]) for r in MICROS])+'</div></section>'
body+='<section class="wrap section">'+section_head(copy('FROM REQUEST TO WORK','DE LA DEMANDE AUX TRAVAUX'),copy('Know the next step.','Connaissez la prochaine étape.'))+steps([(copy('Describe the job','Décrivez les travaux'),copy('Share the location, display details and photos you have.','Transmettez l’emplacement, les détails et vos photos.')),(copy('Review the scope','Examinez la portée'),copy('Confirm the task, parts, access needs and any assessment required.','Confirmez les travaux, pièces, accès et évaluations nécessaires.')),(copy('Approve the quote','Approuvez la soumission'),copy('Review pricing, inclusions and scheduling before work is arranged.','Vérifiez prix, inclusions et calendrier avant d’organiser les travaux.')),(copy('Plan future care','Prévoyez l’entretien'),copy('Discuss replacement or recurring service where it suits the property.','Discutez des remplacements ou d’un entretien adapté à la propriété.'))])+'</section>'
add('/services/',service_title,service_intro,body)
